#!/bin/bash
set -e

HOST_NAME="com.nextdm.host"
CHROME_EXT_ID="ciljeaclhfhipchfaocjmoanpbacibli"
FIREFOX_EXT_ID="nextdm@nextdm.app"

APP_PATH="${1:-$HOME/.local/bin/nextdm-desktop}"
WRAPPER_DIR="$HOME/.local/share/nextdm/browser-host"
WRAPPER_PATH="$WRAPPER_DIR/nextdm-native-host"

mkdir -p "$WRAPPER_DIR"
cat << WRAPPER_EOF > "$WRAPPER_PATH"
#!/bin/sh
# Generated by NextDM. Entry point for browser native messaging.
NEXTDM_APP='$APP_PATH'
export NEXTDM_APP
exec "\$NEXTDM_APP" --native-messaging "\$@"
WRAPPER_EOF

chmod +x "$WRAPPER_PATH"

CHROME_MANIFEST=$(cat << CHROME_EOF
{
  "name": "$HOST_NAME",
  "description": "NextDM download handoff host",
  "path": "$WRAPPER_PATH",
  "type": "stdio",
  "allowed_origins": [
    "chrome-extension://$CHROME_EXT_ID/"
  ]
}
CHROME_EOF
)

FIREFOX_MANIFEST=$(cat << FIREFOX_EOF
{
  "name": "$HOST_NAME",
  "description": "NextDM download handoff host",
  "path": "$WRAPPER_PATH",
  "type": "stdio",
  "allowed_extensions": [
    "$FIREFOX_EXT_ID"
  ]
}
FIREFOX_EOF
)

# Install Chrome / Chromium manifests
for dir in \
  "$HOME/.config/chromium/NativeMessagingHosts" \
  "$HOME/.config/google-chrome/NativeMessagingHosts" \
  "$HOME/.config/BraveSoftware/Brave-Browser/NativeMessagingHosts" \
  "$HOME/.config/microsoft-edge/NativeMessagingHosts"; do
  mkdir -p "$dir"
  echo "$CHROME_MANIFEST" > "$dir/$HOST_NAME.json"
done

# Install Firefox manifest
mkdir -p "$HOME/.mozilla/native-messaging-hosts"
echo "$FIREFOX_MANIFEST" > "$HOME/.mozilla/native-messaging-hosts/$HOST_NAME.json"

# Unpack extensions into ~/.local/share/nextdm/browser-extension
mkdir -p "$HOME/.local/share/nextdm/browser-extension/chromium"
mkdir -p "$HOME/.local/share/nextdm/browser-extension/firefox"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
rsync -a "$SCRIPT_DIR/extensions/chromium/" "$HOME/.local/share/nextdm/browser-extension/chromium/"
rsync -a "$SCRIPT_DIR/extensions/firefox/" "$HOME/.local/share/nextdm/browser-extension/firefox/"

echo "Native messaging manifests and extensions are installed."
echo ""
echo "=== Chrome / Chromium / Brave ==="
echo "1. Open chrome://extensions"
echo "2. Enable 'Developer mode' (top right)"
echo "3. Click 'Load unpacked' and select:"
echo "   $HOME/.local/share/nextdm/browser-extension/chromium"
echo ""
echo "=== Mozilla Firefox ==="
echo "Install the official approved add-on from Mozilla Add-ons (AMO):"
echo "👉 https://addons.mozilla.org/en-US/firefox/addon/nextdm-integration/"
